import { chevronDownIcon } from '@tweakpad/ui/icons/chevron-down';
import { chevronRightIcon } from '@tweakpad/ui/icons/chevron-right';
import { navigationIcons } from '@tweakpad/ui/icons/navigation';
export function setupKbdExample(root) {
  for (const icon of root.querySelectorAll('tp-icon[data-key-icon]'))
    icon.icon = { ...navigationIcons, down: chevronDownIcon, right: chevronRightIcon }[
      icon.dataset.keyIcon
    ];
  return () => {};
}

setupKbdExample(document.getElementById('kbd-input'));

